    ],
    STORE_MANAGER: [{ type: "CRITICAL", title: "Freezer Temperature Abnormal", store: "Store 101 - Dairy Dept", desc: "Chiller #1 Temp 8.2°C", link: "x_fresh_guard_360_issue_list.do?sysparm_query=u_risk_level=critical" }],
    FOOD_SAFETY_OFFICER: [{ type: "CRITICAL", title: "Bakery Prep Table Sanitation Violation", store: "Store 101", desc: "Sanitation score below 75%", link: "x_fresh_guard_360_issue_list.do?sysparm_query=u_risk_level=critical" }],
    MAINTENANCE_TEAM: [{ type: "CRITICAL", title: "Walk-In Freezer Compressor Leak", store: "Store 101", desc: "Ticket #INS-1001 - Urgent Repair Needed", link: "x_fresh_guard_360_inspection_list.do?sysparm_query=u_status!=completed" }],
