window.onload = function() {
    renderDashboard();
    refreshAiForRole(currentRole);
    if (window.LIVE_SERVER_COUNTS) {
        if (window.LIVE_SERVER_COUNTS.issues) updateKpiValue("Food Safety Issues", window.LIVE_SERVER_COUNTS.issues);
        if (window.LIVE_SERVER_COUNTS.critical) updateKpiValue("Critical Issues", window.LIVE_SERVER_COUNTS.critical);
        if (window.LIVE_SERVER_COUNTS.stores) {
            updateKpiValue("Total Stores", window.LIVE_SERVER_COUNTS.stores);
            updateKpiValue("My Stores", window.LIVE_SERVER_COUNTS.stores);
            updateKpiValue("Assigned Stores", window.LIVE_SERVER_COUNTS.stores);
        }
        if (window.LIVE_SERVER_COUNTS.capas) updateKpiValue("Open CAPA", window.LIVE_SERVER_COUNTS.capas);
        if (window.LIVE_SERVER_COUNTS.empTodayTasks) updateKpiValue("Today's Tasks", window.LIVE_SERVER_COUNTS.empTodayTasks);
        if (window.LIVE_SERVER_COUNTS.empPending) updateKpiValue("Pending Tasks", window.LIVE_SERVER_COUNTS.empPending);
        if (window.LIVE_SERVER_COUNTS.checklists) updateKpiValue("Checklists Completed", window.LIVE_SERVER_COUNTS.checklists);
    }
    fetchLiveCountsFromServiceNow();
};

function fetchLiveCountsFromServiceNow() {
    var userToken = window.g_ck || '';

    fetch('/api/now/table/x_fresh_guard_360_issue?sysparm_limit=1', {
        headers: { 'Accept': 'application/json', 'X-UserToken': userToken }
    }).then(function(res) {
        var total = res.headers.get('X-Total-Count');
        if (total) updateKpiValue("Food Safety Issues", total);
    }).catch(function(e) {});

    fetch('/api/now/table/x_fresh_guard_360_issue?sysparm_query=u_risk_level=critical&sysparm_limit=1', {
        headers: { 'Accept': 'application/json', 'X-UserToken': userToken }
    }).then(function(res) {
        var total = res.headers.get('X-Total-Count');
        if (total) updateKpiValue("Critical Issues", total);
    }).catch(function(e) {});

    fetch('/api/now/table/x_fresh_guard_360_store?sysparm_limit=1', {
        headers: { 'Accept': 'application/json', 'X-UserToken': userToken }
    }).then(function(res) {
        var total = res.headers.get('X-Total-Count');
        if (total) {
            updateKpiValue("Total Stores", total);
            updateKpiValue("My Stores", total);
            updateKpiValue("Assigned Stores", total);
        }
    }).catch(function(e) {});

    fetch('/api/now/table/x_fresh_guard_360_capa?sysparm_query=u_status!=completed^u_status!=closed&sysparm_limit=1', {
        headers: { 'Accept': 'application/json', 'X-UserToken': userToken }
    }).then(function(res) {
        var total = res.headers.get('X-Total-Count');
        if (total) updateKpiValue("Open CAPA", total);
    }).catch(function(e) {});

    fetch('/api/now/table/x_fresh_guard_360_checklist?sysparm_query=u_status!=completed&sysparm_limit=1', {
        headers: { 'Accept': 'application/json', 'X-UserToken': userToken }
    }).then(function(res) {
        var total = res.headers.get('X-Total-Count');
        if (total) updateKpiValue("Today's Tasks", total);
    }).catch(function(e) {});

    fetch('/api/now/table/x_fresh_guard_360_checklist?sysparm_query=u_status=pending&sysparm_limit=1', {
        headers: { 'Accept': 'application/json', 'X-UserToken': userToken }
    }).then(function(res) {
        var total = res.headers.get('X-Total-Count');
        if (total) updateKpiValue("Pending Tasks", total);
    }).catch(function(e) {});

    fetch('/api/now/table/x_fresh_guard_360_checklist?sysparm_query=u_status=completed&sysparm_limit=1', {
        headers: { 'Accept': 'application/json', 'X-UserToken': userToken }
    }).then(function(res) {
        var total = res.headers.get('X-Total-Count');
        if (total) updateKpiValue("Checklists Completed", total);
    }).catch(function(e) {});
}

function updateKpiValue(label, newCount) {
    for (var roleKey in roleConfigs) {
        if (roleConfigs.hasOwnProperty(roleKey)) {
            var config = roleConfigs[roleKey];
            if (config && config.kpis) {
                for (var i = 0; i < config.kpis.length; i++) {
                    if (config.kpis[i].label === label) {
                        config.kpis[i].val = newCount.toString();
                    }
                }
            }
        }
    }
    renderDashboard();
}

function switchRole(newRole) {
    currentRole = newRole;
    renderDashboard();
    refreshAiForRole(newRole); // AUTOMATIC REFRESH ON ROLE SWITCH
}

function renderDashboard() {
    var config = roleConfigs[currentRole] || roleConfigs["ADMIN"];

    document.getElementById("dashboardSubTitle").innerText = config.title + " — Real-Time Operations Analytics";
    document.getElementById("roleBadge").innerText = config.badge;
    document.getElementById("roleBadge").style.backgroundColor = config.color;
    document.getElementById("roleScopeDesc").innerText = config.scopeDesc;

    var kpiHtml = "";
    for (var i = 0; i < config.kpis.length; i++) {
        var k = config.kpis[i];
        kpiHtml += '<div onclick="window.open(\'' + k.link + '\', \'_blank\')" style="background: #ffffff; border-radius: 10px; border: 1px solid #e2e8f0; padding: 14px 16px; display: flex; flex-direction: column; justify-content: space-between; cursor: pointer; box-shadow: 0 1px 4px rgba(0,0,0,0.05);">';
        kpiHtml += '  <div style="display: flex; align-items: flex-start; gap: 10px;">';
        kpiHtml += '    <div style="width: 40px; height: 40px; border-radius: 10px; background: #f1f5f9; border: 1px solid #cbd5e1; color: ' + config.color + '; display: flex; align-items: center; justify-content: center; font-size: 1.15rem; flex-shrink: 0;">' + k.icon + '</div>';
        kpiHtml += '    <div><span style="font-size: 0.75rem; font-weight: 600; color: #64748b; display: block;">' + k.label + '</span><span style="font-size: 1.5rem; font-weight: 800; color: #0f172a; line-height: 1.2;">' + k.val + '</span></div>';
        kpiHtml += '  </div>';
        kpiHtml += '  <div style="margin-top: 10px; padding-top: 6px; border-top: 1px solid #f1f5f9; display: flex; justify-content: space-between; align-items: center;"><span style="font-size: 0.72rem; color: ' + config.color + '; font-weight: 700;">View Filtered List ➔</span></div>';
        kpiHtml += '</div>';
    }
    document.getElementById("kpiContainer").innerHTML = kpiHtml;

    var actions = priorityActions[currentRole] || priorityActions["ADMIN"];
    document.getElementById("actionCenterCount").innerText = actions.length + " Critical Actions";
    var actHtml = "";
    for (var j = 0; j < actions.length; j++) {
        var a = actions[j];
        var bColor = a.type === "CRITICAL" ? "#dc2626" : "#ea580c";
        actHtml += '<div style="background: #fef2f2; border-left: 4px solid ' + bColor + '; border-radius: 8px; padding: 12px 14px; border: 1px solid #fee2e2;">';
        actHtml += '  <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 4px;"><span style="font-size: 0.68rem; font-weight: 800; color: #ffffff; background: ' + bColor + '; padding: 2px 6px; border-radius: 4px;">' + a.type + '</span><span style="font-size: 0.72rem; color: #64748b; font-weight: 600;">' + a.store + '</span></div>';
        actHtml += '  <h4 style="font-size: 0.82rem; font-weight: 700; color: #0f172a; margin: 4px 0;">' + a.title + '</h4>';
        actHtml += '  <p style="font-size: 0.72rem; color: #475569; margin: 0 0 8px 0;">' + a.desc + '</p>';
        actHtml += '  <a href="' + a.link + '" target="_blank" style="font-size: 0.72rem; color: #ffffff; background: ' + bColor + '; border-radius: 4px; padding: 3px 8px; text-decoration: none; font-weight: 700; display: inline-block;">View Critical Record ➔</a>';
        actHtml += '</div>';
    }
    document.getElementById("priorityActionList").innerHTML = actHtml;

    renderMainSections();

    var empSection = document.getElementById("employeeChecklistSection");
    if (currentRole === "EMPLOYEE") { empSection.style.display = "block"; renderEmployeeChecklistForm(); } else { empSection.style.display = "none"; }

    var repHtml = "";
    for (var r = 0; r < config.reports.length; r++) {
        var rName = config.reports[r];
        var rUrl = getReportUrl(rName);
        repHtml += '<div onclick="window.open(\'' + rUrl + '\', \'_blank\')" style="background: #ffffff; border: 1px solid #e2e8f0; border-radius: 8px; padding: 12px; display: flex; align-items: center; justify-content: space-between; cursor: pointer;">';
        repHtml += '  <div style="display: flex; align-items: center; gap: 8px;"><span style="font-size: 1rem; color: ' + config.color + ';">📄</span><span style="font-size: 0.78rem; font-weight: 700; color: #1e293b;">' + rName + '</span></div>';
        repHtml += '  <span style="font-size: 0.7rem; color: ' + config.color + '; font-weight: 700;">Run ➔</span>';
        repHtml += '</div>';
    }
    document.getElementById("roleReportsGrid").innerHTML = repHtml;
}

function getReportUrl(reportName) {
    if (reportName.indexOf("Store") !== -1) return "x_fresh_guard_360_store_list.do";
    if (reportName.indexOf("Safety") !== -1 || reportName.indexOf("Risk") !== -1) return "x_fresh_guard_360_issue_list.do";
    if (reportName.indexOf("CAPA") !== -1) return "x_fresh_guard_360_capa_list.do";
    if (reportName.indexOf("Maintenance") !== -1) return "x_fresh_guard_360_inspection_list.do";
    return "x_fresh_guard_360_checklist_list.do";
}

function renderMainSections() {
    var html = "";
    if (currentRole === "ADMIN" || currentRole === "REGIONAL_MANAGER") {
        html += '<div style="background: #ffffff; border: 1px solid #cbd5e1; border-radius: 12px; padding: 16px;">';
        html += '  <div style="display: flex; justify-content: space-between; align-items: center; margin-bottom: 12px;"><h3 style="font-size: 0.9rem; font-weight: 800; color: #0f172a; margin: 0;">🏢 Enterprise Store Performance (All 6 Stores)</h3><a href="x_fresh_guard_360_store_list.do" target="_blank" style="font-size: 0.75rem; color: #2563eb; font-weight: 700; text-decoration: none;">View All 6 Stores ➔</a></div>';
        html += '  <table style="width: 100%; border-collapse: collapse; font-size: 0.78rem; text-align: left;">';
        html += '    <thead><tr style="background: #f8fafc; color: #64748b;"><th style="padding: 8px;">Store Name</th><th style="padding: 8px;">Region</th><th style="padding: 8px;">Safety Score</th><th style="padding: 8px;">Open CAPAs</th><th style="padding: 8px;">Status</th></tr></thead>';
        html += '    <tbody>';
        for (var s = 0; s < allStoresList.length; s++) {
            var st = allStoresList[s];
            html += '      <tr style="border-bottom: 1px solid #f1f5f9;"><td style="padding: 8px; font-weight: 700; color: #0f172a;"><a href="x_fresh_guard_360_store_list.do?sysparm_query=u_store_number=' + st.number + '" target="_blank" style="color: #2563eb; text-decoration: none;">' + st.name + '</a></td><td style="padding: 8px;">' + st.region + '</td><td style="padding: 8px; color: #16a34a; font-weight: 700;">' + st.score + '</td><td style="padding: 8px;">' + st.capas + '</td><td style="padding: 8px;"><span style="background: ' + st.badgeBg + '; color: ' + st.badgeColor + '; padding: 2px 6px; border-radius: 4px; font-size: 0.7rem; font-weight: 700;">' + st.status + '</span></td></tr>';
        }
        html += '    </tbody></table></div>';
    } else if (currentRole === "EMPLOYEE") {
        html += '<div style="background: #ffffff; border: 1px solid #cbd5e1; border-radius: 12px; padding: 16px;"><h3 style="font-size: 0.9rem; font-weight: 800; color: #e11d48; margin-bottom: 8px;">👤 Store Staff Task Center</h3><p style="font-size: 0.8rem; color: #475569; margin: 0;">Authorized view for Store 101 Staff. Complete your mandatory daily food safety checklist form below.</p></div>';
    } else {
        html += '<div style="background: #ffffff; border: 1px solid #cbd5e1; border-radius: 12px; padding: 16px;"><h3 style="font-size: 0.9rem; font-weight: 800; color: #0f172a; margin-bottom: 12px;">🛡️ Role Specific Operational Tasks</h3><p style="font-size: 0.8rem; color: #475569;">All metrics active for ' + currentRole + '.</p></div>';
    }
    document.getElementById("mainSectionsContainer").innerHTML = html;
}

